var i=115;var a=[{id:`cooking-115-01`,theoryId:115,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What helps make a chickpea purée smoother?`,ua:`Що допомагає зробити пюре з нуту гладкішим?`},explanation:{en:`Fully hydrated, tender legumes break down more evenly in a blender.`,ua:`Добре зволожені й м’які бобові рівномірніше подрібнюються.`},options:[{id:`a`,text:{en:`Cook chickpeas fully tender and add liquid gradually`,ua:`Зварити нут до повної м’якості й поступово додавати рідину`}},{id:`b`,text:{en:`Blend dry hard chickpeas without cooking`,ua:`Збивати сирий твердий нут без варіння`}},{id:`c`,text:{en:`Add sand for texture`,ua:`Додавати пісок для текстури`}}],answer:{optionIds:[`a`]}},{id:`cooking-115-02`,theoryId:115,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Chickpea purée may become thicker after refrigeration.`,ua:`Пюре з нуту може загусати після охолодження.`},explanation:{en:`Cooling, hydration and starch/protein networks can change consistency.`,ua:`Охолодження, гідратація та крохмально-білкові структури можуть змінювати консистенцію.`},answer:{value:!0}},{id:`cooking-115-03`,theoryId:115,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match legume purée issues to adjustments.`,ua:`Поєднайте проблеми пюре з бобових з коригуваннями.`},explanation:{en:`Tenderness, hydration and balance are separate variables.`,ua:`М’якість, гідратація та смаковий баланс — різні чинники.`},leftItems:[{id:`l1`,text:{en:`Grainy hummus`,ua:`Зернистий хумус`}},{id:`l2`,text:{en:`Too-thick bean purée`,ua:`Надто густе пюре з квасолі`}},{id:`l3`,text:{en:`Bland lentil purée`,ua:`Прісне пюре із сочевиці`}}],rightItems:[{id:`r3`,text:{en:`Adjust acid and seasoning`,ua:`Відкоригувати кислоту й приправи`}},{id:`r2`,text:{en:`Add liquid slowly`,ua:`Потроху додати рідину`}},{id:`r1`,text:{en:`Cook chickpeas more tender`,ua:`Доварити нут до більшої м’якості`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-115-04`,theoryId:115,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Your hummus becomes soupy after adding too much water at once. What is the best lesson?`,ua:`Хумус став рідким після додавання забагато води відразу. Який висновок?`},explanation:{en:`Controlled hydration prevents overshooting the target consistency.`,ua:`Поступова гідратація не дає перевищити бажану кількість рідини.`},options:[{id:`a`,text:{en:`Add water in small portions while checking texture`,ua:`Додавати воду малими порціями та перевіряти текстуру`}},{id:`b`,text:{en:`Always add all liquid before tasting or blending`,ua:`Завжди додавати всю рідину одразу`}},{id:`c`,text:{en:`Use raw dried chickpeas to thicken immediately`,ua:`Загущувати негайно сирим сухим нутом`}}],answer:{optionIds:[`a`]}},{id:`cooking-115-05`,theoryId:115,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which claim about bean purées is incorrect?`,ua:`Яке твердження про пюре з квасолі неправильне?`},explanation:{en:`Blending does not replace safe cooking of dried beans.`,ua:`Подрібнення не замінює безпечного варіння сухих бобів.`},options:[{id:`a`,text:{en:`Cooking time affects smoothness`,ua:`Час варіння впливає на гладкість`}},{id:`b`,text:{en:`Oil may affect mouthfeel`,ua:`Олія може впливати на відчуття в роті`}},{id:`c`,text:{en:`Pureeing raw dry beans makes them safe without cooking`,ua:`Подрібнення сирих сухих бобів робить їх безпечними без варіння`}}],answer:{optionIds:[`c`]}}];var n={theoryId:115,exercises:a};export{n as default,a as exercises,i as theoryId};